240	 * TODO: Remove once @a2a-js/sdk handles these aliases natively.
241	 */
242	export function normalizeAgentCard(card: unknown): AgentCard {
243	  if (!isObject(card)) {
244	    throw new Error('Agent card is missing.');
245	  }
