137	/** Minimal shape needed by helper functions, avoids generic TOutput constraints. */
138	interface RemoteAgentRef {
139	  name: string;
140	  agentCardUrl?: string;
141	  agentCardJson?: string;
142	}
143	
144	/**
145	 * Derives the AgentCardLoadOptions from a RemoteAgentDefinition.
146	 * Throws if neither agentCardUrl nor agentCardJson is present.
147	 */
148	export function getAgentCardLoadOptions(
149	  def: RemoteAgentRef,
150	): AgentCardLoadOptions {
151	  if (def.agentCardJson) {
152	    return { type: 'json', json: def.agentCardJson };
153	  }
154	  if (def.agentCardUrl) {
155	    return { type: 'url', url: def.agentCardUrl };
156	  }
157	  throw new Error(
158	    `Remote agent '${def.name}' has neither agentCardUrl nor agentCardJson`,
159	  );
160	}
161	
162	/**
163	 * Extracts a target URL for auth providers from a RemoteAgentDefinition.
164	 * For URL-based agents, returns the agentCardUrl.
165	 * For JSON-based agents, attempts to parse the URL from the inline card JSON.
166	 * Returns undefined if no URL can be determined.
167	 */
168	export function getRemoteAgentTargetUrl(
169	  def: RemoteAgentRef,
170	): string | undefined {
171	  if (def.agentCardUrl) {
172	    return def.agentCardUrl;
173	  }
174	  if (def.agentCardJson) {
175	    try {
176	      const parsed: unknown = JSON.parse(def.agentCardJson);
177	      // eslint-disable-next-line @typescript-eslint/no-unsafe-type-assertion
178	      const card = parsed as AgentCard;
179	      if (card.url) {
180	        return card.url;
181	      }
182	    } catch {
183	      // JSON parse will fail properly later in loadAgent
184	    }
185	  }
186	  return undefined;
187	}
