43	/**
44	 * Manages the discovery, loading, validation, and registration of
45	 * AgentDefinitions.
46	 */
47	export class AgentRegistry {
48	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
49	  private readonly agents = new Map<string, AgentDefinition<any>>();
50	  // eslint-disable-next-line @typescript-eslint/no-explicit-any
51	  private readonly allDefinitions = new Map<string, AgentDefinition<any>>();
52	
53	  private initialized = false;
54	
55	  constructor(private readonly config: Config) {}
56	
57	  /**
58	   * Discovers and loads agents.
59	   */
60	  async initialize(): Promise<void> {
61	    if (this.initialized) {
62	      await this.loadAgents();
63	      return;
64	    }
65	    this.initialized = true;
66	
67	    coreEvents.on(CoreEvent.ModelChanged, this.onModelChanged);
68	
69	    await this.loadAgents();
70	  }
71	
72	  private onModelChanged = () => {
73	    this.refreshAgents('local').catch((e) => {
74	      debugLogger.error(
75	        '[AgentRegistry] Failed to refresh agents on model change:',
76	        e,
77	      );
78	    });
79	  };
80	
81	  /**
82	   * Clears the current registry and re-scans for agents.
83	   */
84	  async reload(): Promise<void> {
85	    this.config.getA2AClientManager()?.clearCache();
86	    await this.config.reloadAgents();
87	    this.agents.clear();
88	    this.allDefinitions.clear();
89	    await this.loadAgents();
90	    coreEvents.emitAgentsRefreshed();
91	  }
92	
93	  /**
94	   * Acknowledges and registers a previously unacknowledged agent.
95	   */
96	  async acknowledgeAgent(agent: AgentDefinition): Promise<void> {
97	    const ackService = this.config.getAcknowledgedAgentsService();
98	    const projectRoot = this.config.getProjectRoot();
99	    if (agent.metadata?.hash) {
100	      await ackService.acknowledge(
101	        projectRoot,
102	        agent.name,
103	        agent.metadata.hash,
104	      );
105	      await this.registerAgent(agent);
106	      coreEvents.emitAgentsRefreshed();
107	    }
108	  }
109	
110	  /**
111	   * Disposes of resources and removes event listeners.
112	   */
113	  dispose(): void {
114	    coreEvents.off(CoreEvent.ModelChanged, this.onModelChanged);
115	  }
116	
117	  private async loadAgents(): Promise<void> {
118	    this.agents.clear();
119	    this.allDefinitions.clear();
120	    this.loadBuiltInAgents();
121	
122	    // Clear old dynamic rules before reloading
123	    this.config.getPolicyEngine()?.removeRulesBySource(DYNAMIC_RULE_SOURCE);
124	
125	    if (!this.config.isAgentsEnabled()) {
126	      return;
127	    }
128	
129	    // Load user-level agents: ~/.gemini/agents/
130	    const userAgentsDir = Storage.getUserAgentsDir();
131	    const userAgents = await loadAgentsFromDirectory(userAgentsDir);
132	    for (const error of userAgents.errors) {
133	      debugLogger.warn(
134	        `[AgentRegistry] Error loading user agent: ${error.message}`,
135	      );
136	      coreEvents.emitFeedback('error', `Agent loading error: ${error.message}`);
137	    }
138	    await Promise.allSettled(
139	      userAgents.agents.map(async (agent) => {
140	        try {
141	          await this.registerAgent(agent);
142	        } catch (e) {
143	          debugLogger.warn(
144	            `[AgentRegistry] Error registering user agent "${agent.name}":`,
145	            e,
146	          );
147	          coreEvents.emitFeedback(
148	            'error',
149	            `Error registering user agent "${agent.name}": ${e instanceof Error ? e.message : String(e)}`,
150	          );
151	        }
152	      }),
153	    );
154	
155	    // Load project-level agents: .gemini/agents/ (relative to Project Root)
156	    const folderTrustEnabled = this.config.getFolderTrust();
157	    const isTrustedFolder = this.config.isTrustedFolder();
158	
159	    if (!folderTrustEnabled || isTrustedFolder) {
160	      const projectAgentsDir = this.config.storage.getProjectAgentsDir();
161	      const projectAgents = await loadAgentsFromDirectory(projectAgentsDir);
162	      for (const error of projectAgents.errors) {
163	        coreEvents.emitFeedback(
164	          'error',
165	          `Agent loading error: ${error.message}`,
166	        );
167	      }
168	
169	      const ackService = this.config.getAcknowledgedAgentsService();
170	      const projectRoot = this.config.getProjectRoot();
171	      const unacknowledgedAgents: AgentDefinition[] = [];
172	      const agentsToRegister: AgentDefinition[] = [];
173	
174	      for (const agent of projectAgents.agents) {
175	        // If it's a remote agent, use the agentCardUrl as the hash.
176	        // This allows multiple remote agents in a single file to be tracked independently.
177	        if (agent.kind === 'remote') {
178	          if (!agent.metadata) {
179	            agent.metadata = {};
180	          }
181	          agent.metadata.hash =
182	            agent.agentCardUrl ??
183	            (agent.agentCardJson
184	              ? crypto
185	                  .createHash('sha256')
186	                  .update(agent.agentCardJson)
187	                  .digest('hex')
188	              : undefined);
189	        }
190	
191	        if (!agent.metadata?.hash) {
192	          agentsToRegister.push(agent);
193	          continue;
194	        }
195	
196	        const isAcknowledged = await ackService.isAcknowledged(
197	          projectRoot,
198	          agent.name,
199	          agent.metadata.hash,
200	        );
201	
202	        if (isAcknowledged) {
203	          agentsToRegister.push(agent);
204	        } else {
205	          unacknowledgedAgents.push(agent);
206	        }
